package com.nook.widgets;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.media.session.*;
import android.media.session.MediaController;
import android.os.*;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;

/** Foreground music controls, with real seeking, queue and session volume. */
public final class NowPlayingActivity extends Activity {
    private final Handler handler=new Handler(Looper.getMainLooper());
    private int widget;private JSONObject config;private MediaController player;private MusicState state;
    private LinearLayout page,custom,transport,shortcuts;private TextView connection,volumeLabel;private TextView title,artist,album,status,elapsed,duration,queueButton;private ImageView artwork,previous,primary,next;private SeekBar seek,volume;
    private boolean dragging,volumeDragging,resumed;private String screenKey="";
    private final MediaController.Callback callback=new MediaController.Callback(){@Override public void onMetadataChanged(android.media.MediaMetadata metadata){refresh(true);}@Override public void onPlaybackStateChanged(PlaybackState playback){refresh(false);}@Override public void onQueueChanged(List<MediaSession.QueueItem> queue){refresh(false);}@Override public void onAudioInfoChanged(MediaController.PlaybackInfo info){refresh(false);}@Override public void onSessionDestroyed(){screenKey="";refresh(true);}};
    private final MediaSessionManager.OnActiveSessionsChangedListener active=list->refresh(true);
    private final Runnable tick=new Runnable(){public void run(){if(!resumed)return;refresh(false);handler.postDelayed(this,1000);}};
    @Override public void onCreate(Bundle saved){super.onCreate(saved);widget=getIntent().getIntExtra("widget",-1);config=MusicWidgets.settings(this,widget);build();if(getIntent().getBooleanExtra("source",false)){MediaController source=MediaAccess.controller(this,config);if(openSource(source)){finish();return;}}refresh(true);}
    private ImageView icon(String description,int resource,int size,Runnable action){ImageView image=new ImageView(this);image.setImageResource(resource);image.setColorFilter(Ui.TEXT);image.setPadding(Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14),Ui.dp(this,14));image.setContentDescription(description);LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(Ui.dp(this,size),Ui.dp(this,size));params.setMargins(Ui.dp(this,8),0,Ui.dp(this,8),0);image.setLayoutParams(params);Ui.surface(image,Ui.SURFACE,24);Ui.click(image,action);return image;}
    private void build(){
        LinearLayout root=Ui.column(this);root.setBackgroundColor(Ui.BG);setContentView(root);Ui.insets(this,root);LinearLayout header=Ui.row(this);Ui.pad(header,16,10);header.addView(Ui.iconButton(this,"back","Close now playing",this::finish));TextView heading=Ui.bold(this,"Now Playing",22,Ui.TEXT);heading.setPadding(Ui.dp(this,14),0,0,0);Ui.weight(header,heading);TextView picker=Ui.button(this,"Player",Ui.SURFACE,Ui.ACCENT,()->MusicOptions.choosePlayer(this,config,()->{savePlayer();refresh(true);}));picker.setId(R.id.music_player_picker);header.addView(picker);root.addView(header);
        ScrollView scroll=new ScrollView(this);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));page=Ui.column(this);Ui.pad(page,24,18);scroll.addView(page);artwork=new ImageView(this);artwork.setScaleType(ImageView.ScaleType.FIT_CENTER);artwork.setContentDescription("Album artwork");page.addView(artwork,new LinearLayout.LayoutParams(-1,Ui.dp(this,300)));Ui.gap(page,24);
        title=Ui.bold(this,"Ready when you are",27,Ui.TEXT);title.setMaxLines(2);page.addView(title);artist=Ui.text(this,"",17,Ui.MUTED);page.addView(artist);album=Ui.text(this,"",13,Ui.MUTED);page.addView(album);Ui.gap(page,14);status=Ui.text(this,"",12,Ui.ACCENT);page.addView(status);connection=Ui.button(this,"Connect media access",Ui.SURFACE,Ui.ACCENT,()->startActivity(WidgetUtilityActivity.intent(this,"media_access",widget,"")));connection.setId(R.id.music_connect);page.addView(connection);
        seek=new SeekBar(this);seek.setId(R.id.music_seek);seek.setMax(1000);seek.setContentDescription("Seek through this track");page.addView(seek,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));LinearLayout times=Ui.row(this);elapsed=Ui.text(this,"0:00",12,Ui.MUTED);Ui.weight(times,elapsed);duration=Ui.text(this,"",12,Ui.MUTED);times.addView(duration);page.addView(times);
        seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){dragging=true;}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&state!=null)elapsed.setText(MusicState.time(state.duration*value/1000));}public void onStopTrackingTouch(SeekBar bar){dragging=false;if(state!=null&&state.can("seek"))MediaAccess.transport(player,"seek",state.duration*bar.getProgress()/1000);}});
        transport=Ui.row(this);transport.setGravity(Gravity.CENTER);Ui.gap(page,20);previous=icon("Previous track",R.drawable.ic_music_previous,56,()->act(config.optInt("musicTransport",0)==1?"back":"previous"));primary=icon("Play",R.drawable.ic_music_play,76,()->act("toggle"));primary.setId(R.id.music_primary);next=icon("Next track",R.drawable.ic_music_next,56,()->act(config.optInt("musicTransport",0)==1?"forward":"next"));transport.addView(previous);transport.addView(primary);transport.addView(next);page.addView(transport);Ui.gap(page,22);
        shortcuts=Ui.row(this);queueButton=Ui.button(this,"Queue",Ui.SURFACE,Ui.TEXT,this::queue);queueButton.setId(R.id.music_queue);Ui.weight(shortcuts,queueButton);Ui.weight(shortcuts,Ui.button(this,"Open music app",Ui.SURFACE,Ui.ACCENT,()->{if(!openSource(player))Toast.makeText(this,"The player has no launch action. Open it from your home screen.",Toast.LENGTH_LONG).show();}));page.addView(shortcuts);Ui.gap(page,18);
        volumeLabel=Ui.text(this,"PLAYER VOLUME",11,Ui.MUTED);page.addView(volumeLabel);volume=new SeekBar(this);volume.setId(R.id.music_volume);volume.setContentDescription("Player volume");page.addView(volume,new LinearLayout.LayoutParams(-1,Ui.dp(this,48)));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){volumeDragging=true;}public void onProgressChanged(SeekBar bar,int value,boolean user){if(user&&player!=null){MediaController.PlaybackInfo info=player.getPlaybackInfo();if(info!=null&&info.getVolumeControl()==android.media.VolumeProvider.VOLUME_CONTROL_ABSOLUTE)player.setVolumeTo(Math.min(value,info.getMaxVolume()),0);}}public void onStopTrackingTouch(SeekBar bar){volumeDragging=false;}});
        custom=Ui.column(this);page.addView(custom);Ui.gap(page,18);page.addView(Ui.button(this,"Media access settings",Ui.SURFACE,Ui.MUTED,()->startActivity(WidgetUtilityActivity.intent(this,"media_access",widget,""))));
    }
    private void savePlayer(){if(widget<=0)return;android.appwidget.AppWidgetProviderInfo info=android.appwidget.AppWidgetManager.getInstance(this).getAppWidgetInfo(widget);if(info==null)return;JSONObject root=Store.config(this,widget),settings=Widgets.kindOf(info.provider).equals("universal")?UniversalWidget.pageSettings(root,"music"):root;ExtraData.put(settings,"musicPackage",config.optString("musicPackage",""));Store.config(this,widget,root);MusicWidgets.updateAll(this);}
    private void act(String operation){MediaAccess.transport(player,operation,0);handler.postDelayed(()->refresh(false),100);}
    private boolean openSource(MediaController selected){
        try{if(selected!=null&&selected.getSessionActivity()!=null){selected.getSessionActivity().send();return true;}String name=selected==null?config.optString("musicPackage",""):selected.getPackageName();if(name.isEmpty())return false;Intent launch=getPackageManager().getLaunchIntentForPackage(name);if(launch!=null){startActivity(launch);return true;}}catch(PendingIntent.CanceledException|ActivityNotFoundException|SecurityException ignored){}return false;
    }
    private void refresh(boolean force){
        MediaController selected=(dragging||volumeDragging)&&player!=null?MediaAccess.find(this,player.getSessionToken()):MediaAccess.controller(this,config);boolean changed=player==null?selected!=null:selected==null||!player.getSessionToken().equals(selected.getSessionToken());if(changed){if(player!=null)player.unregisterCallback(callback);player=selected;if(player!=null)player.registerCallback(callback,handler);force=true;}
        state=new MusicState(this,player);String key=MediaAccess.allowed(this)+"|"+state.title+"|"+state.artist+"|"+state.album+"|"+(state.playback==null?"":state.playback.getCustomActions().stream().map(action->action.getAction()+action.getName()).collect(java.util.stream.Collectors.joining("|")));if(force||!key.equals(screenKey)){screenKey=key;artwork.setImageBitmap(MusicArt.artwork(state.art,config,640,WidgetDesign.colors(config,"music").accent,config.optInt("variant",0)==3));title.setText(state.connected?state.title:MediaAccess.allowed(this)?"Ready when you are":"Connect your music");artist.setText(state.connected?state.artist:MediaAccess.allowed(this)?"Start playback in your music or podcast app.":"Enable media access to connect your player.");album.setText(state.album);renderCustom();}
        connection.setVisibility(MediaAccess.allowed(this)?View.GONE:View.VISIBLE);artwork.setVisibility(state.connected?View.VISIBLE:View.GONE);seek.setVisibility(state.connected?View.VISIBLE:View.GONE);((View)elapsed.getParent()).setVisibility(state.connected?View.VISIBLE:View.GONE);transport.setVisibility(state.connected?View.VISIBLE:View.GONE);shortcuts.setVisibility(state.connected?View.VISIBLE:View.GONE);volume.setVisibility(state.connected?View.VISIBLE:View.GONE);volumeLabel.setVisibility(state.connected?View.VISIBLE:View.GONE);
        status.setText(state.connected?state.app+" · "+state.status:config.optString("musicPackage","").isEmpty()?"No active media session":"Waiting for "+MediaAccess.appName(this,config.optString("musicPackage")));primary.setImageResource(state.playing?R.drawable.ic_music_pause:R.drawable.ic_music_play);primary.setContentDescription(state.playing?"Pause playback":"Play");primary.setEnabled(state.can("toggle"));primary.setAlpha(state.can("toggle")?1:.3f);boolean podcast=config.optInt("musicTransport",0)==1;previous.setEnabled(state.can(podcast?"back":"previous"));next.setEnabled(state.can(podcast?"forward":"next"));previous.setAlpha(previous.isEnabled()?1:.3f);next.setAlpha(next.isEnabled()?1:.3f);if(podcast){previous.setImageBitmap(MusicArt.skip(-15,Ui.TEXT));next.setImageBitmap(MusicArt.skip(30,Ui.TEXT));previous.setContentDescription("Back 15 seconds");next.setContentDescription("Forward 30 seconds");}
        seek.setEnabled(state.can("seek")&&state.duration>0);if(!dragging){seek.setProgress(state.duration>0?(int)(state.position*1000/state.duration):0);elapsed.setText(MusicState.time(state.position));}duration.setText(state.duration>0?MusicState.time(state.duration):"Live / unknown length");MediaController.PlaybackInfo output=player==null?null:player.getPlaybackInfo();volume.setEnabled(output!=null&&output.getVolumeControl()==android.media.VolumeProvider.VOLUME_CONTROL_ABSOLUTE);volumeLabel.setText(output!=null&&output.getVolumeControl()==android.media.VolumeProvider.VOLUME_CONTROL_ABSOLUTE?"PLAYER VOLUME":"VOLUME · USE THE MUSIC APP");if(output!=null&&!volumeDragging){volume.setMax(Math.max(1,output.getMaxVolume()));volume.setProgress(output.getCurrentVolume());}List<MediaSession.QueueItem> queue=player==null?null:player.getQueue();queueButton.setText(queue==null||queue.isEmpty()?"Queue unavailable":"Queue · "+queue.size());queueButton.setEnabled(queue!=null&&!queue.isEmpty());
    }
    private void renderCustom(){
        custom.removeAllViews();MediaController owner=player;if(owner==null||state.playback==null)return;
        for(PlaybackState.CustomAction action:state.playback.getCustomActions().subList(0,Math.min(6,state.playback.getCustomActions().size()))){TextView button=Ui.button(this,action.getName().toString(),Ui.SURFACE,Ui.ACCENT,()->{MediaController active=MediaAccess.find(this,owner.getSessionToken());if(active==null)return;PlaybackState currentState=active.getPlaybackState();if(currentState==null)return;for(PlaybackState.CustomAction current:currentState.getCustomActions())if(current.getAction().equals(action.getAction())){active.getTransportControls().sendCustomAction(current,current.getExtras());break;}});custom.addView(button);}
    }
    private void queue(){
        MediaController owner=player;List<MediaSession.QueueItem> queue=owner==null?null:owner.getQueue();if(queue==null||queue.isEmpty())return;PlaybackState snapshot=owner.getPlaybackState();boolean selectable=MediaAccess.enabled(snapshot,"queue");String[] labels=new String[queue.size()];for(int n=0;n<queue.size();n++){MediaSession.QueueItem item=queue.get(n);labels[n]=(snapshot!=null&&item.getQueueId()==snapshot.getActiveQueueItemId()?"● ":"")+item.getDescription().getTitle();}
        new AlertDialog.Builder(this).setTitle(selectable?"Play from queue":"Player queue · read only").setItems(labels,(dialog,n)->{if(!selectable)return;MediaController active=MediaAccess.find(this,owner.getSessionToken());if(active==null){Toast.makeText(this,"That player is no longer active.",Toast.LENGTH_SHORT).show();return;}List<MediaSession.QueueItem> current=active.getQueue();long wanted=queue.get(n).getQueueId();if(current!=null&&current.stream().anyMatch(item->item.getQueueId()==wanted))MediaAccess.transport(active,"queue",wanted);}).setNegativeButton("Close",null).show();
    }
    @Override protected void onResume(){super.onResume();resumed=true;try{if(MediaAccess.allowed(this))getSystemService(MediaSessionManager.class).addOnActiveSessionsChangedListener(active,MediaAccess.listener(this),handler);}catch(SecurityException ignored){}handler.removeCallbacks(tick);handler.post(tick);}
    @Override protected void onPause(){resumed=false;handler.removeCallbacksAndMessages(null);try{getSystemService(MediaSessionManager.class).removeOnActiveSessionsChangedListener(active);}catch(SecurityException ignored){}if(player!=null){player.unregisterCallback(callback);player=null;}super.onPause();}
}
